package dev.veltraph.client.observation.nativeinput;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class NativeCryptoPrimitiveOrderTest {
 @Test void cipherCapturesOutputBeforeLaterMutation(){Object b=new Object(),c=new Object();byte[] in={9,1,2,8},out={0,4,5,0};var x=new NativeCryptoPrimitiveOrder.CipherUpdate(b,c,new byte[]{1,2},in,1,2,out,1);assertTrue(x.viable());x.returned(2,true);out[1]=7;assertArrayEquals(new byte[]{4,5},x.finish(b,true));assertNull(x.finish(b,true));}
 @Test void cipherRejectsForeignInputAndFakeOutputWithoutPrimitiveReturn(){Object b=new Object(),c=new Object();var x=new NativeCryptoPrimitiveOrder.CipherUpdate(b,c,new byte[]{1,2},new byte[]{1,3},0,2,new byte[2],0);assertFalse(x.viable());x.returned(2,true);assertNull(x.finish(b,true));var y=new NativeCryptoPrimitiveOrder.CipherUpdate(b,c,new byte[]{1,2},new byte[]{1,2},0,2,new byte[2],0);assertNull(y.finish(b,true));}
 @Test void cipherInputChangedDuringOperationCannotCertify(){Object b=new Object(),c=new Object();byte[] in={1,2};var x=new NativeCryptoPrimitiveOrder.CipherUpdate(b,c,in,in,0,2,new byte[2],0);in[0]=3;x.returned(2,true);assertNull(x.finish(b,true));}
 @Test void cipherWrongCountDuplicateAndAbnormalClosureRefuse(){Object b=new Object(),c=new Object();var x=new NativeCryptoPrimitiveOrder.CipherUpdate(b,c,new byte[]{1},new byte[]{1},0,1,new byte[1],0);x.returned(1,true);x.returned(1,true);assertNull(x.finish(b,true));var y=new NativeCryptoPrimitiveOrder.CipherUpdate(b,c,new byte[]{1},new byte[]{1},0,1,new byte[1],0);y.returned(0,true);assertNull(y.finish(b,true));var z=new NativeCryptoPrimitiveOrder.CipherUpdate(b,c,new byte[]{1},new byte[]{1},0,1,new byte[1],0);z.returned(1,true);assertNull(z.finish(b,false));}
 @Test void compressionHeaderDerivesPayloadFromImmutableOriginalFrame(){var x=NativeCryptoPrimitiveOrder.compressed(new byte[]{(byte)130,1,7,8});assertNotNull(x);assertEquals(130,x.decodedSize);assertArrayEquals(new byte[]{7,8},x.payload());var p=x.payload();p[0]=2;assertArrayEquals(new byte[]{7,8},x.payload());assertNull(NativeCryptoPrimitiveOrder.compressed(new byte[]{0,1}));assertNull(NativeCryptoPrimitiveOrder.compressed(new byte[]{(byte)128,(byte)128,(byte)128,(byte)128,(byte)128,1}));}
 @Test void inflateRetainsNativeResultAndNormalSetInput(){Object o=new Object(),i=new Object(),b=new Object(),out=new Object();var x=new NativeCryptoPrimitiveOrder.Inflate(o,i,b,4,NativeCryptoPrimitiveOrder.compressed(new byte[]{2,7,8}));assertTrue(x.beforeSet(i,b,4,new byte[]{7,8}));x.afterSet(i,b,4,new byte[]{7,8},true);assertTrue(x.beforeInflate(o,i,out,5,2,new byte[]{7,8}));byte[] produced={1,2};x.afterInflate(out,7,2,new byte[]{7,8},produced,true);produced[0]=9;assertArrayEquals(new byte[]{1,2},x.finish(o,true,new byte[]{7,8}));assertNull(x.finish(o,true,new byte[]{7,8}));}
 @Test void inflateWithoutNativeSetInputAndForeignReceiverRefuse(){Object o=new Object(),i=new Object(),b=new Object();var x=new NativeCryptoPrimitiveOrder.Inflate(o,i,b,0,NativeCryptoPrimitiveOrder.compressed(new byte[]{1,7}));assertFalse(x.beforeInflate(o,i,new Object(),0,1,new byte[]{7}));var y=new NativeCryptoPrimitiveOrder.Inflate(o,i,b,0,NativeCryptoPrimitiveOrder.compressed(new byte[]{1,7}));assertFalse(y.beforeSet(new Object(),b,0,new byte[]{7}));}
 @Test void inflateMutationAndShortNativeOutputRefuse(){Object o=new Object(),i=new Object(),b=new Object(),out=new Object();var x=new NativeCryptoPrimitiveOrder.Inflate(o,i,b,0,NativeCryptoPrimitiveOrder.compressed(new byte[]{2,7}));x.beforeSet(i,b,0,new byte[]{7});x.afterSet(i,b,0,new byte[]{7},true);assertTrue(x.beforeInflate(o,i,out,0,2,new byte[]{7}));x.afterInflate(out,1,1,new byte[]{7},new byte[]{3},true);assertNull(x.finish(o,true,new byte[]{7}));var y=new NativeCryptoPrimitiveOrder.Inflate(o,i,b,0,NativeCryptoPrimitiveOrder.compressed(new byte[]{2,7}));y.beforeSet(i,b,0,new byte[]{7});y.afterSet(i,b,0,new byte[]{8},true);assertFalse(y.beforeInflate(o,i,out,0,2,new byte[]{7}));}
 @Test void inflateAbnormalOuterCompletionPoisonsRetainedOutput(){Object o=new Object(),i=new Object(),b=new Object(),out=new Object();var x=new NativeCryptoPrimitiveOrder.Inflate(o,i,b,0,NativeCryptoPrimitiveOrder.compressed(new byte[]{1,7}));x.beforeSet(i,b,0,new byte[]{7});x.afterSet(i,b,0,new byte[]{7},true);x.beforeInflate(o,i,out,0,1,new byte[]{7});x.afterInflate(out,1,1,new byte[]{7},new byte[]{2},true);assertNull(x.finish(o,false,new byte[]{7}));}
}
